use std::collections::HashMap;

use od_isa::execute::{
    self, Cr0Profile, Cr4Profile, PagedCpl0Cr0WpProbeV1, PagedCpl0Cr3ProbeV1,
    PagedCpl0FirmwareBootV1, PagedCpl0ProbeV1, PagedCpl0StackProbeV1, PagedProbeExit,
    PagedProbeRejection,
};
use od_isa::{
    AccessContext, AccessKind, AccessOrigin, ArchitecturalFault, CpuActivity, GuestMemory,
    InstructionMode, LongModeState, MemoryError, OperandSize, PortIo, PrivilegeLevel, Register,
    StiShadow,
};

const RIP: u64 = 0x4000;
const DATA: u64 = 0x8000;
const CODE_PHYSICAL: usize = 0x1000;
const DATA_PHYSICAL: usize = 0x3000;
const CR0: u64 = Cr0Profile::BASE;
const CR4: u64 = Cr4Profile::BASE;
const DEFINED: u64 = od_isa::INTEGER_FLAGS & !(1 << 4);

struct Memory {
    bytes: Vec<u8>,
    pages: HashMap<u64, usize>,
    fetches: Vec<(u64, AccessContext)>,
    reads: usize,
    read_addresses: Vec<(u64, usize)>,
    writes: usize,
    write_addresses: Vec<u64>,
    fail_fetch: Option<MemoryError>,
    fail_fetch_at: Option<(u64, MemoryError)>,
    fail_read: Option<MemoryError>,
    fail_read_at: Option<(u64, MemoryError)>,
    fail_write: Option<MemoryError>,
    fail_write_on: Option<(usize, MemoryError)>,
}

impl Memory {
    fn new(code: &[u8]) -> Self {
        let mut bytes = vec![0; 0x5000];
        bytes[CODE_PHYSICAL..CODE_PHYSICAL + code.len()].copy_from_slice(code);
        let mut pages = HashMap::new();
        pages.insert(RIP, CODE_PHYSICAL);
        pages.insert(DATA, DATA_PHYSICAL);
        Self {
            bytes,
            pages,
            fetches: Vec::new(),
            reads: 0,
            read_addresses: Vec::new(),
            writes: 0,
            write_addresses: Vec::new(),
            fail_fetch: None,
            fail_fetch_at: None,
            fail_read: None,
            fail_read_at: None,
            fail_write: None,
            fail_write_on: None,
        }
    }

    fn physical(&self, address: u64) -> Result<usize, MemoryError> {
        let base = self
            .pages
            .get(&(address & !0xfff))
            .copied()
            .ok_or(MemoryError::Unmapped {
                address,
                access: AccessKind::Read,
            })?;
        Ok(base + (address as usize & 0xfff))
    }
}

impl GuestMemory for Memory {
    fn fetch(&mut self, address: u64, context: AccessContext) -> Result<u8, MemoryError> {
        self.fetches.push((address, context));
        if let Some((fail_address, error)) = &self.fail_fetch_at {
            if address == *fail_address {
                return Err(error.clone());
            }
        }
        if let Some(error) = &self.fail_fetch {
            return Err(error.clone());
        }
        let physical = self.physical(address)?;
        self.bytes
            .get(physical)
            .copied()
            .ok_or(MemoryError::Unmapped {
                address,
                access: AccessKind::Fetch,
            })
    }

    fn read(
        &mut self,
        address: u64,
        _: AccessContext,
        destination: &mut [u8],
    ) -> Result<(), MemoryError> {
        self.reads += 1;
        self.read_addresses.push((address, destination.len()));
        if let Some(error) = &self.fail_read {
            return Err(error.clone());
        }
        if let Some((fault_address, error)) = &self.fail_read_at {
            let end = address.saturating_add(destination.len() as u64);
            if address <= *fault_address && *fault_address < end {
                return Err(error.clone());
            }
        }
        let physical = self.physical(address)?;
        let source = self
            .bytes
            .get(physical..physical + destination.len())
            .ok_or(MemoryError::Unmapped {
                address,
                access: AccessKind::Read,
            })?;
        destination.copy_from_slice(source);
        Ok(())
    }

    fn write(&mut self, address: u64, _: AccessContext, source: &[u8]) -> Result<(), MemoryError> {
        self.writes += 1;
        self.write_addresses.push(address);
        if let Some((write_number, error)) = &self.fail_write_on
            && self.writes == *write_number
        {
            return Err(error.clone());
        }
        if let Some(error) = &self.fail_write {
            return Err(error.clone());
        }
        let physical = self.physical(address)?;
        let destination = self
            .bytes
            .get_mut(physical..physical + source.len())
            .ok_or(MemoryError::Unmapped {
                address,
                access: AccessKind::Write,
            })?;
        destination.copy_from_slice(source);
        Ok(())
    }

    fn read_for_write_integer(
        &mut self,
        address: u64,
        context: AccessContext,
        size: OperandSize,
    ) -> Result<u64, MemoryError> {
        self.read_integer(address, context, size)
    }
    fn atomic_exchange_integer(
        &mut self,
        _: u64,
        _: AccessContext,
        _: OperandSize,
        _: u64,
    ) -> Result<u64, MemoryError> {
        unreachable!("probe MOV does not use atomic exchange")
    }

    fn atomic_fetch_add_integer(
        &mut self,
        _: u64,
        _: AccessContext,
        _: OperandSize,
        _: u64,
    ) -> Result<u64, MemoryError> {
        unreachable!("probe MOV does not use atomic add")
    }

    fn atomic_compare_exchange_integer(
        &mut self,
        _: u64,
        _: AccessContext,
        _: OperandSize,
        _: u64,
        _: u64,
    ) -> Result<u64, MemoryError> {
        unreachable!("probe MOV does not use atomic compare exchange")
    }

    fn mfence(&mut self, _: AccessContext) -> Result<(), MemoryError> {
        unreachable!("probe does not issue a memory fence")
    }
}

#[derive(Default)]
struct Pio {
    input: u8,
    reads: Vec<u16>,
    writes: Vec<(u16, u8)>,
    fail_read: bool,
    fail_write: bool,
}

impl PortIo for Pio {
    type Error = &'static str;

    fn read_u8(&mut self, port: u16) -> Result<u8, Self::Error> {
        self.reads.push(port);
        if self.fail_read {
            Err("read")
        } else {
            Ok(self.input)
        }
    }

    fn write_u8(&mut self, port: u16, value: u8) -> Result<(), Self::Error> {
        self.writes.push((port, value));
        if self.fail_write {
            Err("write")
        } else {
            Ok(())
        }
    }
}

fn context(mode: InstructionMode, privilege: PrivilegeLevel) -> AccessContext {
    AccessContext {
        mode,
        privilege,
        origin: AccessOrigin::DescriptorTable,
    }
}

fn state() -> LongModeState {
    LongModeState {
        cr3: None,
        rip: RIP,
        rflags: 0x8d7,
        cr0: Some(CR0),
        cr4: Some(CR4),
        activity: Some(CpuActivity::Running),
        sti_shadow: Some(StiShadow::Clear),
        ..LongModeState::default()
    }
}

fn step(
    state: &mut LongModeState,
    memory: &mut Memory,
    pio: &mut Pio,
    context: AccessContext,
) -> execute::PagedProbeResult<&'static str> {
    execute::step_paged_probe(PagedCpl0ProbeV1, state, memory, pio, context, DEFINED)
}

fn step_with_defined(
    state: &mut LongModeState,
    memory: &mut Memory,
    pio: &mut Pio,
    context: AccessContext,
    defined: u64,
) -> execute::PagedProbeResult<&'static str> {
    execute::step_paged_probe(PagedCpl0ProbeV1, state, memory, pio, context, defined)
}

fn page_fault(error_code: u32, address: u64) -> MemoryError {
    MemoryError::Architectural(od_isa::ArchitecturalFault {
        vector: 14,
        error_code: Some(error_code),
        linear_address: Some(address),
    })
}

fn memory_with_code_at(code: &[u8], rip: u64) -> Memory {
    let mut memory = Memory::new(&[]);
    let page = rip & !0xfff;
    let offset = (rip & 0xfff) as usize;
    memory.pages.insert(page, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + offset..CODE_PHYSICAL + offset + code.len()].copy_from_slice(code);
    memory
}

#[test]
fn legacy_paged_probe_profile_keeps_stack_forms_unsupported() {
    for code in [[0x51], [0x58]] {
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr[Register::Rcx as usize] = 0x1122_3344_5566_7788;
        cpu.gpr[Register::Rax as usize] = 0xaabb_ccdd_eeff_0011;
        cpu.gpr[Register::Rsp as usize] = 0x2000;
        let before = cpu.clone();
        let mut pio = Pio::default();

        let result = step(
            &mut cpu,
            &mut memory,
            &mut pio,
            context(InstructionMode::Long64, PrivilegeLevel::Ring0),
        );

        assert_eq!(result.exit, PagedProbeExit::Unsupported { opcode: code[0] });
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(cpu, before);
        assert_eq!(memory.writes, 0);
    }
}

#[test]
fn paged_mov_load_uses_nonidentity_fetch_and_preserves_flags() {
    let mut memory = Memory::new(&[0x48, 0x8b, 0x03]);
    memory.bytes[DATA_PHYSICAL..DATA_PHYSICAL + 8]
        .copy_from_slice(&0x0123_4567_89ab_cdefu64.to_le_bytes());
    let mut cpu = state();
    cpu.gpr[Register::Rbx as usize] = DATA;
    let flags = cpu.rflags;
    let mut pio = Pio::default();

    let result = step(
        &mut cpu,
        &mut memory,
        &mut pio,
        context(InstructionMode::Long64, PrivilegeLevel::Ring0),
    );

    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    assert_eq!(cpu.gpr[Register::Rax as usize], 0x0123_4567_89ab_cdef);
    assert_eq!(cpu.rip, RIP + 3);
    assert_eq!(cpu.rflags, flags);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(memory.fetches.len(), 3);
    assert!(memory.fetches.iter().all(|(_, context)| {
        context.origin == AccessOrigin::Explicit && context.privilege == PrivilegeLevel::Ring0
    }));
    assert_eq!(memory.reads, 1);
}

#[test]
fn paged_mov_store_commits_memory_then_retires_once() {
    let mut memory = Memory::new(&[0x48, 0x89, 0x0b]);
    let mut cpu = state();
    cpu.gpr[Register::Rbx as usize] = DATA;
    cpu.gpr[Register::Rcx as usize] = 0xfedc_ba98_7654_3210;
    let mut pio = Pio::default();

    let result = step(
        &mut cpu,
        &mut memory,
        &mut pio,
        context(InstructionMode::Long64, PrivilegeLevel::Ring0),
    );

    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(cpu.rip, RIP + 3);
    assert_eq!(
        &memory.bytes[DATA_PHYSICAL..DATA_PHYSICAL + 8],
        &0xfedc_ba98_7654_3210u64.to_le_bytes()
    );
    assert_eq!(memory.writes, 1);
}

#[test]
fn rust_helper_mov_rsp_disp8_rdx_stores_qword_and_preserves_cpu_state() {
    let code = [0x48, 0x89, 0x54, 0x24, 0x30]; // MOV [RSP+0x30],RDX
    let mut memory = Memory::new(&code);
    memory.bytes[DATA_PHYSICAL + 0x30..DATA_PHYSICAL + 0x38]
        .copy_from_slice(&0xfeed_face_cafe_beefu64.to_le_bytes());
    let mut cpu = state();
    cpu.gpr = gpr_patterns();
    cpu.gpr[Register::Rsp as usize] = DATA;
    cpu.gpr[Register::Rdx as usize] = 0x0123_4567_89ab_cdef;
    cpu.rflags = 0x8d7;
    let before = cpu.clone();
    let mut pio = Pio::default();

    let result = step(&mut cpu, &mut memory, &mut pio, ring0());

    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    assert_eq!(result.rflags_defined, DEFINED);
    let mut expected = before.clone();
    expected.rip += code.len() as u64;
    assert_eq!(cpu, expected);
    assert_eq!(memory.write_addresses, [DATA + 0x30]);
    assert_eq!(memory.writes, 1);
    assert_eq!(memory.reads, 0);
    assert_eq!(
        &memory.bytes[DATA_PHYSICAL + 0x30..DATA_PHYSICAL + 0x38],
        &before.gpr[Register::Rdx as usize].to_le_bytes()
    );
    assert!(pio.reads.is_empty() && pio.writes.is_empty());
}

#[test]
fn rust_helper_mov_rsp_disp8_rdx_injected_write_page_fault_is_atomic() {
    let code = [0x48, 0x89, 0x54, 0x24, 0x30];
    let mut memory = Memory::new(&code);
    memory.bytes[DATA_PHYSICAL + 0x30..DATA_PHYSICAL + 0x38]
        .copy_from_slice(&0xfeed_face_cafe_beefu64.to_le_bytes());
    memory.fail_write = Some(page_fault(0x2, DATA + 0x30));
    let mut cpu = state();
    cpu.gpr = gpr_patterns();
    cpu.gpr[Register::Rsp as usize] = DATA;
    cpu.gpr[Register::Rdx as usize] = 0x0123_4567_89ab_cdef;
    let before = cpu.clone();
    let mut pio = Pio::default();

    let result = step(&mut cpu, &mut memory, &mut pio, ring0());

    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 14,
            error_code: Some(0x2),
            linear_address: Some(DATA + 0x30),
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!(memory.write_addresses, [DATA + 0x30]);
    assert_eq!(memory.writes, 1);
    assert_eq!(
        &memory.bytes[DATA_PHYSICAL + 0x30..DATA_PHYSICAL + 0x38],
        &0xfeed_face_cafe_beefu64.to_le_bytes()
    );
    assert!(pio.reads.is_empty() && pio.writes.is_empty());
}

#[test]
fn rust_helper_mov_rsp_disp8_rdx_fetch_fault_is_atomic() {
    let code = [0x48, 0x89, 0x54, 0x24];
    let rip = RIP + 0xffc;
    let mut memory = memory_with_code_at(&code, rip);
    memory.fail_fetch_at = Some((rip + 4, page_fault(0x10, rip + 4)));
    let mut cpu = state();
    cpu.rip = rip;
    cpu.gpr[Register::Rsp as usize] = DATA;
    let before = cpu.clone();

    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 14,
            error_code: Some(0x10),
            linear_address: Some(rip + 4),
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!(memory.writes, 0);
}

#[test]
fn rust_helper_mov_rsp_disp8_rdx_neighbours_stay_unsupported_without_mutation() {
    let cases: &[(&[u8], u8)] = &[
        (&[0x48, 0x89, 0x54, 0x24, 0x2f], 0x89), // adjacent displacement
        (&[0x48, 0x89, 0x54, 0x24, 0x31], 0x89), // adjacent displacement
        (&[0x48, 0x89, 0x4c, 0x24, 0x30], 0x89), // RCX source
        (&[0x48, 0x89, 0x44, 0x24, 0x30], 0x89), // RAX source
        (&[0x48, 0x89, 0x54, 0x64, 0x30], 0x89), // alternate SIB scale
        (&[0x48, 0x89, 0x94, 0x24, 0x30, 0, 0, 0], 0x89), // disp32
        (&[0x40, 0x89, 0x54, 0x24, 0x30], 0x89), // dword width
        (&[0x66, 0x48, 0x89, 0x54, 0x24, 0x30], 0x89), // operand prefix
        (&[0x40, 0x48, 0x89, 0x54, 0x24, 0x30], 0x89), // redundant REX
        (&[0x48, 0x89, 0x54, 0x20, 0x30], 0x89), // alternate SIB index
    ];
    for (bytes, opcode) in cases {
        let mut memory = Memory::new(bytes);
        memory.bytes[DATA_PHYSICAL + 0x30..DATA_PHYSICAL + 0x38]
            .copy_from_slice(&0xfeed_face_cafe_beefu64.to_le_bytes());
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[Register::Rsp as usize] = DATA;
        let before = cpu.clone();
        let mut pio = Pio::default();

        let result = step(&mut cpu, &mut memory, &mut pio, ring0());

        assert_eq!(
            result.exit,
            PagedProbeExit::Unsupported { opcode: *opcode },
            "{bytes:02x?}"
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(result.rflags_defined, DEFINED);
        assert_eq!(cpu, before, "{bytes:02x?}");
        assert_eq!(memory.writes, 0, "{bytes:02x?}");
        assert!(pio.reads.is_empty() && pio.writes.is_empty());
    }
}

#[test]
fn rust_helper_mov_rsp_disp8_rdx_is_unsupported_in_cpl3_profile() {
    let bytes = [0x48, 0x89, 0x54, 0x24, 0x30];
    let mut memory = Memory::new(&bytes);
    let mut cpu = state();
    cpu.cr3 = Some(0x1000);
    cpu.gpr[Register::Rsp as usize] = DATA;
    cpu.gpr[Register::Rdx as usize] = 0x0123_4567_89ab_cdef;
    let before = cpu.clone();
    let result = execute::step_paged_cpl3_mov(
        &mut cpu,
        &mut memory,
        context(InstructionMode::Long64, PrivilegeLevel::Ring3),
        0xd00,
        DEFINED,
    );
    assert!(matches!(result.exit, PagedProbeExit::Unsupported { .. }));
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!(memory.writes, 0);
}

#[test]
fn rust_helper_mov_rsp_disp8_rsi_stores_qword_and_preserves_cpu_state() {
    let code = [0x48, 0x89, 0x74, 0x24, 0x10]; // MOV [RSP+0x10],RSI
    let mut memory = Memory::new(&code);
    memory.bytes[DATA_PHYSICAL + 0x10..DATA_PHYSICAL + 0x18]
        .copy_from_slice(&0xfeed_face_cafe_beefu64.to_le_bytes());
    let mut cpu = state();
    cpu.gpr = gpr_patterns();
    cpu.gpr[Register::Rsp as usize] = DATA;
    cpu.gpr[Register::Rsi as usize] = 0x0123_4567_89ab_cdef;
    cpu.rflags = 0x8d7;
    let before = cpu.clone();
    let mut pio = Pio::default();

    let result = step(&mut cpu, &mut memory, &mut pio, ring0());

    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    assert_eq!(result.rflags_defined, DEFINED);
    let mut expected = before.clone();
    expected.rip += code.len() as u64;
    assert_eq!(cpu, expected);
    assert_eq!(memory.write_addresses, [DATA + 0x10]);
    assert_eq!(memory.writes, 1);
    assert_eq!(memory.reads, 0);
    assert_eq!(
        &memory.bytes[DATA_PHYSICAL + 0x10..DATA_PHYSICAL + 0x18],
        &before.gpr[Register::Rsi as usize].to_le_bytes()
    );
    assert!(pio.reads.is_empty() && pio.writes.is_empty());
}

