#[test]
fn rust_helper_add_eax_eax_updates_dword_flags_and_zero_extends_rax() {
    const CF: u64 = 1 << 0;
    const PF: u64 = 1 << 2;
    const AF: u64 = 1 << 4;
    const ZF: u64 = 1 << 6;
    const SF: u64 = 1 << 7;
    const OF: u64 = 1 << 11;
    const ARITH_FLAGS: u64 = CF | PF | AF | ZF | SF | OF;
    let code = [0x01, 0xc0]; // ADD EAX,EAX
    let cases = [
        (0x0000_0000u32, ZF | PF),
        (0x0000_0001, 0),
        (0x1234_5678, AF | PF),
        (0x7fff_ffff, AF | SF | OF),
        (0x8000_0000, CF | PF | ZF | OF),
        (0x8000_0008, CF | AF | OF),
        (0xffff_fff0, CF | SF),
    ];

    for (eax, expected_flags) in cases {
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[Register::Rax as usize] = 0xfeed_face_0000_0000 | u64::from(eax);
        cpu.rflags = 0x8d7;
        let before = cpu.clone();
        let initial_defined = DEFINED & !ARITH_FLAGS;

        let result = step_with_defined(
            &mut cpu,
            &mut memory,
            &mut Pio::default(),
            ring0(),
            initial_defined,
        );

        assert_eq!(result.exit, PagedProbeExit::Retired);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(result.rflags_defined, initial_defined | ARITH_FLAGS);
        let mut expected = before;
        expected.gpr[Register::Rax as usize] = u64::from(eax.wrapping_add(eax));
        expected.rflags = (expected.rflags & !ARITH_FLAGS) | expected_flags;
        expected.rip += code.len() as u64;
        assert_eq!(cpu, expected, "EAX={eax:#010x}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
        assert!(memory.write_addresses.is_empty());
    }
}

