#[test]
fn rust_helper_jnz_rel32_minus_17f_checks_canonicality_only_for_taken_target() {
    let code = [0x0f, 0x85, 0x81, 0xfe, 0xff, 0xff];
    // Not-taken fall-through crosses from the lower canonical range and is
    // deferred until the next instruction fetch.
    let rip = 0x0000_7fff_ffff_fffa;
    let mut memory = Memory::new(&[]);
    memory.pages.insert(rip & !0xfff, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + 0xffa..CODE_PHYSICAL + 0x1000].copy_from_slice(&code);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.rflags |= 1 << 6; // Not taken.
    let before = cpu.clone();

    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    assert_eq!(result.rflags_defined, DEFINED);
    let mut expected = before;
    expected.rip = 0x0000_8000_0000_0000;
    assert_eq!(cpu, expected);

    // The negative displacement crosses from the high canonical range into a
    // noncanonical hole only when the branch is taken.
    let rip = 0xffff_8000_0000_0100;
    let mut memory = Memory::new(&[]);
    memory.pages.insert(rip & !0xfff, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + 0x100..CODE_PHYSICAL + 0x106].copy_from_slice(&code);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.rflags &= !(1 << 6); // Taken to a noncanonical target.
    let before = cpu.clone();

    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 13,
            error_code: Some(0),
            linear_address: None,
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!((memory.reads, memory.writes), (0, 0));
}

