#[test]
fn rust_helper_ja_rel32_0x2cd_obeys_cf_zf_and_preserves_flags() {
    let code = [0x0f, 0x87, 0xcd, 0x02, 0, 0]; // JA +0x2cd
    for cf in [false, true] {
        for zero in [false, true] {
            for defined_mask in [0u64, 1 << 0, 1 << 6, (1 << 0) | (1 << 6)] {
                let defined = DEFINED & !(1 | (1 << 6)) | defined_mask;
                let mut memory = Memory::new(&code);
                let mut cpu = state();
                cpu.gpr = gpr_patterns();
                cpu.rflags = (cpu.rflags & !((1 << 0) | (1 << 6)))
                    | if cf { 1 << 0 } else { 0 }
                    | if zero { 1 << 6 } else { 0 };
                let before = cpu.clone();

                let result =
                    step_with_defined(&mut cpu, &mut memory, &mut Pio::default(), ring0(), defined);

                assert_eq!(result.exit, PagedProbeExit::Retired);
                assert_eq!(result.instructions_executed, 1);
                assert_eq!(result.rflags_defined, defined);
                let mut expected = before;
                expected.rip = if !cf && !zero {
                    RIP + 6 + 0x2cd
                } else {
                    RIP + 6
                };
                assert_eq!(
                    cpu, expected,
                    "CF={cf}, ZF={zero}, defined={defined_mask:#x}"
                );
                assert_eq!((memory.reads, memory.writes), (0, 0));
            }
        }
    }
}

#[test]
fn rust_helper_ja_rel32_0x2cd_checks_canonicality_only_when_taken() {
    let code = [0x0f, 0x87, 0xcd, 0x02, 0, 0];
    // With CF set, the branch is not taken: fall-through may be noncanonical,
    // and the unused rel32 target is also noncanonical.
    let rip = 0x0000_7fff_ffff_fffa;
    let mut memory = Memory::new(&[]);
    memory.pages.insert(rip & !0xfff, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + 0xffa..CODE_PHYSICAL + 0x1000].copy_from_slice(&code);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.rflags = (cpu.rflags | 1) & !(1 << 6);
    let before = cpu.clone();
    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());
    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    let mut expected = before;
    expected.rip = 0x0000_8000_0000_0000;
    assert_eq!(cpu, expected);

    let rip = 0x0000_7fff_ffff_fd2d;
    assert_eq!(rip + 6 + 0x2cd, 0x0000_8000_0000_0000);
    let mut memory = Memory::new(&[]);
    memory.pages.insert(rip & !0xfff, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + 0xd2d..CODE_PHYSICAL + 0xd33].copy_from_slice(&code);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.rflags &= !((1 << 0) | (1 << 6));
    let before = cpu.clone();
    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());
    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 13,
            error_code: Some(0),
            linear_address: None,
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!((memory.reads, memory.writes), (0, 0));
}

