#[test]
fn rust_helper_ja_rel32_0x24e_checks_canonicality_only_when_taken() {
    let code = [0x0f, 0x87, 0x4e, 0x02, 0, 0];
    let rip = 0x0000_7fff_ffff_fffa;
    let mut memory = Memory::new(&[]);
    memory.pages.insert(rip & !0xfff, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + 0xffa..CODE_PHYSICAL + 0x1000].copy_from_slice(&code);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.rflags = (cpu.rflags | 1) & !(1 << 6); // CF=1: branch not taken
    let before = cpu.clone();
    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());
    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    let mut expected = before;
    expected.rip = 0x0000_8000_0000_0000; // noncanonical fall-through is not checked
    assert_eq!(cpu, expected);

    let rip = 0x0000_7fff_ffff_fdac;
    assert_eq!(rip + 6 + 0x24e, 0x0000_8000_0000_0000);
    let mut memory = Memory::new(&[]);
    memory.pages.insert(rip & !0xfff, CODE_PHYSICAL);
    memory.bytes[CODE_PHYSICAL + 0xdac..CODE_PHYSICAL + 0xdb2].copy_from_slice(&code);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.rflags &= !((1 << 0) | (1 << 6)); // CF=0 and ZF=0: taken
    let before = cpu.clone();
    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());
    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 13,
            error_code: Some(0),
            linear_address: None,
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!((memory.reads, memory.writes), (0, 0));
}

