#[test]
fn rust_helper_setae_bpl_obeys_cf_and_preserves_flags() {
    let code = [0x40, 0x0f, 0x93, 0xc5]; // SETAE BPL (REX selects BPL rather than CH)
    for cf_defined in [false, true] {
        let defined = if cf_defined {
            DEFINED
        } else {
            DEFINED & !(1 << 0)
        };
        for carry in [false, true] {
            for zero in [false, true] {
                let mut memory = Memory::new(&code);
                let mut cpu = state();
                cpu.gpr = gpr_patterns();
                cpu.gpr[Register::Rbp as usize] = 0xaabb_ccdd_eeff_00aa;
                cpu.rflags = (state().rflags & !((1 << 0) | (1 << 6)))
                    | u64::from(carry)
                    | (u64::from(zero) << 6);
                let before = cpu.clone();

                let result =
                    step_with_defined(&mut cpu, &mut memory, &mut Pio::default(), ring0(), defined);

                assert_eq!(result.exit, PagedProbeExit::Retired);
                assert_eq!(result.instructions_executed, 1);
                assert_eq!(result.rflags_defined, defined);
                let mut expected = before;
                expected.rip = RIP + code.len() as u64;
                expected.gpr[Register::Rbp as usize] =
                    (expected.gpr[Register::Rbp as usize] & !0xff) | u64::from(!carry);
                assert_eq!(
                    cpu, expected,
                    "CF={carry}, ZF={zero}, CF-defined={cf_defined}"
                );
                assert_eq!((memory.reads, memory.writes), (0, 0));
                assert!(memory.write_addresses.is_empty());
            }
        }
    }
}

