#[test]
fn rust_helper_setne_rsp_disp8_07_stores_one_byte_and_preserves_state() {
    let code = [0x0f, 0x95, 0x44, 0x24, 0x07]; // SETNE byte ptr [RSP+7]
    for zero in [false, true] {
        for zf_defined in [false, true] {
            let defined = if zf_defined {
                DEFINED
            } else {
                DEFINED & !(1 << 6)
            };
            let mut memory = Memory::new(&code);
            memory.bytes[DATA_PHYSICAL + 0x16..DATA_PHYSICAL + 0x19]
                .copy_from_slice(&[0xaa, 0xbb, 0xcc]);
            let mut cpu = state();
            cpu.gpr = gpr_patterns();
            cpu.gpr[Register::Rsp as usize] = DATA + 0x10;
            cpu.rflags = (state().rflags & !((1 << 0) | (1 << 6)))
                | 1 // SETNE must not change unrelated CF.
                | (u64::from(zero) << 6);
            let before = cpu.clone();
            let mut pio = Pio::default();

            let result = step_with_defined(&mut cpu, &mut memory, &mut pio, ring0(), defined);

            assert_eq!(result.exit, PagedProbeExit::Retired);
            assert_eq!(result.instructions_executed, 1);
            assert_eq!(result.rflags_defined, defined);
            let mut expected = before;
            expected.rip = RIP + code.len() as u64;
            assert_eq!(cpu, expected, "ZF={zero}, defined={zf_defined}");
            assert_eq!(
                memory.bytes[DATA_PHYSICAL + 0x16..DATA_PHYSICAL + 0x19],
                [0xaa, u8::from(!zero), 0xcc]
            );
            assert_eq!(memory.reads, 0);
            assert_eq!(memory.writes, 1);
            assert_eq!(memory.write_addresses, [DATA + 0x17]);
            assert!(pio.reads.is_empty() && pio.writes.is_empty());
        }
    }
}

#[test]
fn rust_helper_setne_rsp_disp8_07_write_fault_is_atomic() {
    let code = [0x0f, 0x95, 0x44, 0x24, 0x07];
    let rip = RIP;
    let fault_address = DATA + 0x17;
    let mut memory = Memory::new(&code);
    memory.bytes[DATA_PHYSICAL + 0x16..DATA_PHYSICAL + 0x19].copy_from_slice(&[0xaa, 0xbb, 0xcc]);
    memory.fail_write = Some(page_fault(0x2, fault_address));
    let mut cpu = state();
    cpu.rip = rip;
    cpu.gpr = gpr_patterns();
    cpu.gpr[Register::Rsp as usize] = DATA + 0x10;
    cpu.rflags &= !(1 << 6);
    let before = cpu.clone();

    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 14,
            error_code: Some(0x2),
            linear_address: Some(fault_address),
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!(memory.reads, 0);
    assert_eq!(memory.writes, 1);
    assert_eq!(memory.write_addresses, [fault_address]);
    assert_eq!(
        memory.bytes[DATA_PHYSICAL + 0x16..DATA_PHYSICAL + 0x19],
        [0xaa, 0xbb, 0xcc]
    );
}

