#[test]
fn rust_helper_and_ebp_imm32_0xfff_updates_dword_and_logic_flags() {
    const CF: u64 = 1 << 0;
    const PF: u64 = 1 << 2;
    const AF: u64 = 1 << 4;
    const ZF: u64 = 1 << 6;
    const SF: u64 = 1 << 7;
    const OF: u64 = 1 << 11;
    const LOGIC_FLAGS: u64 = CF | PF | ZF | SF | OF;
    let code = [0x81, 0xe5, 0xff, 0x0f, 0, 0]; // AND EBP,0xfff
    let defined = (DEFINED & !(ZF | SF)) | AF;
    for ebp in [
        0x1234_f00fu32,
        0x8000_0000,
        0x7fff_ffff,
        0xffff_ffff,
        0x0000_0800,
        0x0000_0000,
    ] {
        let result_value = ebp & 0xfff;
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[Register::Rbp as usize] = 0xaabb_ccdd_0000_0000 | u64::from(ebp);
        cpu.rflags = 0x8d7;
        let before = cpu.clone();
        let mut result_flags = 0;
        if result_value == 0 {
            result_flags |= ZF;
        }
        if result_value >> 31 != 0 {
            result_flags |= SF;
        }
        if (result_value as u8).count_ones() % 2 == 0 {
            result_flags |= PF;
        }

        let result =
            step_with_defined(&mut cpu, &mut memory, &mut Pio::default(), ring0(), defined);

        assert_eq!(result.exit, PagedProbeExit::Retired);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(result.rflags_defined, (defined & !AF) | LOGIC_FLAGS);
        let mut expected = before;
        expected.gpr[Register::Rbp as usize] = u64::from(result_value);
        expected.rflags = (expected.rflags & !LOGIC_FLAGS) | result_flags;
        expected.rip = RIP + code.len() as u64;
        assert_eq!(cpu, expected, "EBP={ebp:#010x}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
        assert!(memory.write_addresses.is_empty());
    }
}

