                cpu.rflags = 0x2 | (1 << 9) | (1 << 10) | (1 << 18) | CF | SF | OF;
                if initial_af {
                    cpu.rflags |= AF;
                }
                let before = cpu.clone();
                let mut result_flags = 0;
                if value == 0 {
                    result_flags |= ZF;
                }
                if value >> 63 != 0 {
                    result_flags |= SF;
                }
                if (value as u8).count_ones() % 2 == 0 {
                    result_flags |= PF;
                }

