#[test]
fn rust_helper_cmp_rdi_r13_uses_qword_operands_and_preserves_registers() {
    const CF: u64 = 1 << 0;
    const PF: u64 = 1 << 2;
    const AF: u64 = 1 << 4;
    const ZF: u64 = 1 << 6;
    const SF: u64 = 1 << 7;
    const OF: u64 = 1 << 11;
    const ARITH_FLAGS: u64 = CF | PF | AF | ZF | SF | OF;
    let code = [0x4c, 0x39, 0xef]; // CMP RDI,R13
    let cases = [
        (0x1234_5678_9abc_def0, 0x1234_5678_9abc_def0, PF | ZF),
        (0x0000_0001_0000_0000, 1, PF | AF),
        (0, 1, CF | PF | AF | SF),
        (1, 0, 0),
        (i64::MIN as u64, 1, PF | AF | OF),
    ];

    for (rdi, r13, cmp_flags) in cases {
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[Register::Rdi as usize] = rdi;
        cpu.gpr[Register::R13 as usize] = r13;
        cpu.rflags = 0x8d7;
        let before = cpu.clone();
        let mut pio = Pio::default();
        let initial_defined = DEFINED & !ARITH_FLAGS;

        let result = step_with_defined(&mut cpu, &mut memory, &mut pio, ring0(), initial_defined);

        assert_eq!(result.exit, PagedProbeExit::Retired);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(result.rflags_defined, initial_defined | ARITH_FLAGS);
        let mut expected = before;
        expected.rflags = (expected.rflags & !ARITH_FLAGS) | cmp_flags;
        expected.rip += code.len() as u64;
        assert_eq!(cpu, expected, "RDI={rdi:#018x} - R13={r13:#018x}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
        assert!(memory.write_addresses.is_empty());
        assert!(pio.reads.is_empty() && pio.writes.is_empty());
    }
}

#[test]
fn rust_helper_cmp_rdi_r13_fetch_fault_is_atomic() {
    let rip = RIP + 0xffe;
    let code = [0x4c, 0x39];
    let mut memory = memory_with_code_at(&code, rip);
    let mut cpu = state();
    cpu.rip = rip;
    cpu.gpr = gpr_patterns();
    let before = cpu.clone();
    memory.fail_fetch_at = Some((rip + 2, page_fault(0x10, rip + 2)));

    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

    assert_eq!(
        result.exit,
        PagedProbeExit::Fault(od_isa::ArchitecturalFault {
            vector: 14,
            error_code: Some(0x10),
            linear_address: Some(rip + 2),
        })
    );
    assert_eq!(result.instructions_executed, 0);
    assert_eq!(result.rflags_defined, DEFINED);
    assert_eq!(cpu, before);
    assert_eq!((memory.reads, memory.writes), (0, 0));
    assert!(memory.write_addresses.is_empty());
}

