#[test]
fn rust_helper_cmp_r9w_imm8_uses_word_operand_and_preserves_registers() {
    use od_isa::integer_flags::DEFINED_ARITHMETIC_FLAGS;

    const CF: u64 = 1 << 0;
    const PF: u64 = 1 << 2;
    const AF: u64 = 1 << 4;
    const ZF: u64 = 1 << 6;
    const SF: u64 = 1 << 7;
    const OF: u64 = 1 << 11;
    for immediate in [1, 2] {
        let code = [0x66, 0x41, 0x83, 0xf9, immediate];
        let rhs = u64::from(immediate);
        let cases = [
            (0xaabb_ccdd_eeee_0000 | rhs, ZF | PF),
            (0x1122_3344_5555_0000 | (rhs - 1), CF | PF | AF | SF),
            (0x9988_7766_5544_0000 | (rhs + 1), 0),
            (0xfeed_face_cafe_8000 | (rhs - 1), PF | AF | OF),
            (0x1234_5678_9abc_ffff, SF),
        ];
        for (r9, flags) in cases {
            let mut cpu = state();
            cpu.gpr = gpr_patterns();
            cpu.gpr[Register::R9 as usize] = r9;
            cpu.rflags = 0x602 | DEFINED_ARITHMETIC_FLAGS;
            let defined = DEFINED & !DEFINED_ARITHMETIC_FLAGS;
            let mut expected = cpu.clone();
            expected.rip += code.len() as u64;
            expected.rflags = (expected.rflags & !DEFINED_ARITHMETIC_FLAGS) | flags;
            let mut memory = Memory::new(&code);
            let mut pio = Pio::default();

            let result = step_with_defined(&mut cpu, &mut memory, &mut pio, ring0(), defined);

            assert_eq!(result.exit, PagedProbeExit::Retired);
            assert_eq!(result.instructions_executed, 1);
            assert_eq!(result.rflags_defined, defined | DEFINED_ARITHMETIC_FLAGS);
            assert_eq!(cpu, expected, "R9={r9:#018x}, imm8={immediate}");
            assert_eq!((memory.reads, memory.writes), (0, 0));
            assert!(pio.reads.is_empty() && pio.writes.is_empty());
        }
    }
}

