#[test]
fn rust_helper_cmp_r13d_imm8_minus_01_uses_dword_operands_and_preserves_registers() {
    const CF: u64 = 1 << 0;
    const PF: u64 = 1 << 2;
    const AF: u64 = 1 << 4;
    const ZF: u64 = 1 << 6;
    const SF: u64 = 1 << 7;
    const OF: u64 = 1 << 11;
    const ARITH_FLAGS: u64 = CF | PF | AF | ZF | SF | OF;
    let code = [0x41, 0x83, 0xfd, 0xff]; // CMP R13D,-1
    let cases = [
        (0xaaaa_bbbb_ffff_ffff, ZF | PF), // immediate sign-extends; upper qword ignored
        (0x1234_5678_0000_ffff, CF | PF), // dword borrow; word compare would set ZF
        (0xfeed_face_0000_0000, CF | AF),
        (0xcafe_babe_ffff_fffe, CF | PF | AF | SF),
        (0x8765_4321_8000_0000, CF | AF | SF),
        (0x1234_5678_7fff_ffff, CF | PF | SF | OF), // signed positive minus -1 overflows
    ];

    for (r13, cmp_flags) in cases {
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[Register::R13 as usize] = r13;
        cpu.rflags = 0x8d7;
        let before = cpu.clone();
        let mut pio = Pio::default();
        let initial_defined = DEFINED & !ARITH_FLAGS;

        let result = step_with_defined(&mut cpu, &mut memory, &mut pio, ring0(), initial_defined);

        assert_eq!(result.exit, PagedProbeExit::Retired);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(result.rflags_defined, initial_defined | ARITH_FLAGS);
        let mut expected = before;
        expected.rflags = (expected.rflags & !ARITH_FLAGS) | cmp_flags;
        expected.rip += code.len() as u64;
        assert_eq!(cpu, expected, "R13={r13:#018x}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
        assert!(memory.write_addresses.is_empty());
        assert!(pio.reads.is_empty() && pio.writes.is_empty());
    }
}

