#[test]
fn rust_helper_mov_r13d_dword_handoff_field_3c_zero_extends_and_preserves_flags() {
    let code = [0x44, 0x8b, 0x6e, 0x3c]; // MOV R13D,dword ptr [RSI+0x3c]
    let rip = 0x200ef8;
    let value = 0x89ab_cdefu32;
    let mut memory = memory_with_code_at(&code, rip);
    memory.bytes[DATA_PHYSICAL + 0x3c..DATA_PHYSICAL + 0x40].copy_from_slice(&value.to_le_bytes());
    let mut cpu = state();
    cpu.rip = rip;
    cpu.gpr = gpr_patterns();
    cpu.gpr[Register::Rsi as usize] = DATA;
    cpu.gpr[Register::R13 as usize] = 0xaabb_ccdd_eeff_0011;
    cpu.rflags = 0x8d7;
    let before = cpu.clone();

    let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

    assert_eq!(result.exit, PagedProbeExit::Retired);
    assert_eq!(result.instructions_executed, 1);
    assert_eq!(result.rflags_defined, DEFINED);
    let mut expected = before;
    expected.gpr[Register::R13 as usize] = u64::from(value);
    expected.rip = rip + code.len() as u64;
    assert_eq!(cpu, expected);
    assert_eq!(memory.reads, 1);
    assert_eq!(memory.read_addresses, [(DATA + 0x3c, 4)]);
    assert_eq!(memory.writes, 0);
}

