#[test]
fn rust_helper_mov_r8d_dword_handoff_field_44_neighbours_stay_unsupported() {
    let cases: &[(&[u8], u8)] = &[
        (&[0x44, 0x8b, 0x46, 0x43], 0x8b),          // adjacent displacement
        (&[0x44, 0x8b, 0x46, 0x45], 0x8b),          // adjacent displacement
        (&[0x44, 0x8b, 0x76, 0x44], 0x8b),          // R14D destination
        (&[0x44, 0x8b, 0x7e, 0x44], 0x8b),          // R15D destination
        (&[0x44, 0x8b, 0x6e, 0x44], 0x8b),          // R13D destination
        (&[0x45, 0x8b, 0x46, 0x44], 0x8b),          // different REX
        (&[0x4c, 0x8b, 0x46, 0x44], 0x8b),          // qword destination
        (&[0x66, 0x44, 0x8b, 0x46, 0x44], 0x8b),    // word destination
        (&[0xf3, 0x44, 0x8b, 0x46, 0x44], 0x8b),    // REP prefix
        (&[0x40, 0x44, 0x8b, 0x46, 0x44], 0x8b),    // redundant REX
        (&[0x44, 0x8b, 0x06], 0x8b),                // no displacement
        (&[0x44, 0x8b, 0x86, 0x44, 0, 0, 0], 0x8b), // disp32 form
        (&[0x44, 0x89, 0x46, 0x44], 0x89),          // store direction
    ];
    for (bytes, opcode) in cases {
        let mut memory = Memory::new(bytes);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        let before = cpu.clone();
        let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

        assert_eq!(
            result.exit,
            PagedProbeExit::Unsupported { opcode: *opcode },
            "bytes {bytes:02x?}"
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(result.rflags_defined, DEFINED);
        assert_eq!(cpu, before, "bytes {bytes:02x?}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
    }
}

