#[test]
fn rust_helper_mov_eax_or_ebp_imm32_zero_extends_and_preserves_flags() {
    for (opcode, destination, immediate) in [
        (0xb8, Register::Rax, 1),
        (0xb8, Register::Rax, 2),
        (0xb8, Register::Rax, 3),
        (0xb8, Register::Rax, 4),
        (0xb8, Register::Rax, 5),
        (0xb8, Register::Rax, 6),
        (0xb8, Register::Rax, 7),
        (0xbd, Register::Rbp, 1),
    ] {
        let code = [opcode, immediate, 0x00, 0x00, 0x00];
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[destination as usize] = 0xaabb_ccdd_eeff_0011;
        cpu.rflags = 0x8d7;
        let defined = DEFINED ^ (1 << 6);
        let before = cpu.clone();
        let mut pio = Pio::default();

        let result = step_with_defined(&mut cpu, &mut memory, &mut pio, ring0(), defined);

        assert_eq!(result.exit, PagedProbeExit::Retired);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(result.rflags_defined, defined);
        let mut expected = before;
        expected.gpr[destination as usize] = u64::from(immediate);
        expected.rip = RIP + code.len() as u64;
        assert_eq!(cpu, expected);
        assert_eq!((memory.reads, memory.writes), (0, 0));
        assert!(memory.write_addresses.is_empty());
        assert!(pio.reads.is_empty() && pio.writes.is_empty());
    }
}

