#[test]
fn rust_helper_shl_r8_4_uses_qword_result_and_shift_flags() {
    let code = [0x49, 0xc1, 0xe0, 0x04]; // SHL R8,4
    let defined = DEFINED | (1 << 4) | (1 << 11); // AF and OF begin defined.
    // Count four defines CF/SF/ZF/PF; OF and AF become undefined and retain
    // their prior stored values in this implementation.
    let arithmetic_flags = 0x0d5;
    for (input, result_value, result_flags) in [
        (0x0123_4567_89ab_cdefu64, 0x1234_5678_9abc_def0, 0x004),
        (0x0f00_0000_0000_0000, 0xf000_0000_0000_0000, 0x084),
        (0x0800_0000_0000_0000, 0x8000_0000_0000_0000, 0x084),
        (0x1000_0000_0000_0000, 0, 0x045),
        (0x8000_0000_0000_0000, 0, 0x044),
        (0x0f, 0xf0, 0x004),
        (0, 0, 0x044),
    ] {
        assert_eq!(input.wrapping_shl(4), result_value);
        let mut memory = Memory::new(&code);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        cpu.gpr[Register::R8 as usize] = input;
        cpu.rflags = 0x8d7;
        let before = cpu.clone();
        let mut pio = Pio::default();

        let result = step_with_defined(&mut cpu, &mut memory, &mut pio, ring0(), defined);

        assert_eq!(result.exit, PagedProbeExit::Retired);
        assert_eq!(result.instructions_executed, 1);
        assert_eq!(
            result.rflags_defined,
            (defined & !(0x10 | 0x800)) | (arithmetic_flags & !(0x10 | 0x800))
        );
        let mut expected = before;
        expected.gpr[Register::R8 as usize] = result_value;
        expected.rflags = (expected.rflags & !(arithmetic_flags & !0x10)) | result_flags;
        expected.rip = RIP + code.len() as u64;
        assert_eq!(cpu, expected, "R8={input:#018x}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
        assert!(memory.read_addresses.is_empty() && memory.write_addresses.is_empty());
        assert!(pio.reads.is_empty() && pio.writes.is_empty());
    }
}

