#[test]
fn rust_helper_lea_rax_rcx_plus_r11_neighbours_stay_unsupported() {
    let cases: &[(&[u8], u8)] = &[
        (&[0x4a, 0x8d, 0x04, 0x11], 0x8d),       // R10 index, not R11
        (&[0x4a, 0x8d, 0x04, 0x18], 0x8d),       // RAX base, not RCX
        (&[0x4a, 0x8d, 0x0c, 0x19], 0x8d),       // RCX destination
        (&[0x48, 0x8d, 0x04, 0x19], 0x8d),       // missing REX.X
        (&[0x4a, 0x8d, 0x04, 0x59], 0x8d),       // scale 2
        (&[0x42, 0x8d, 0x04, 0x19], 0x8d),       // dword destination
        (&[0x66, 0x4a, 0x8d, 0x04, 0x19], 0x8d), // operand-size prefix
        (&[0x4a, 0x8d, 0x44, 0x19, 0x00], 0x8d), // disp8 present
        (&[0x4a, 0x89, 0x04, 0x19], 0x89),       // MOV, not LEA
        (&[0x40, 0x4a, 0x8d, 0x04, 0x19], 0x8d), // extra REX prefix
    ];
    for (bytes, opcode) in cases {
        let mut memory = Memory::new(bytes);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        let before = cpu.clone();
        let mut pio = Pio::default();
        let result = step(&mut cpu, &mut memory, &mut pio, ring0());
        assert_eq!(
            result.exit,
            PagedProbeExit::Unsupported { opcode: *opcode },
            "{bytes:02x?}"
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(result.rflags_defined, DEFINED);
        assert_eq!(cpu, before, "{bytes:02x?}");
        assert_eq!((memory.reads, memory.writes), (0, 0), "{bytes:02x?}");
        assert!(memory.write_addresses.is_empty());
        assert!(pio.reads.is_empty() && pio.writes.is_empty());
    }
}

