#[test]
fn rust_helper_mov_r8d_rsi_plus_r11_neighbours_stay_unsupported() {
    let cases: &[(&[u8], u8)] = &[
        (&[0x46, 0x8b, 0x04, 0x16], 0x8b),             // R10 index
        (&[0x46, 0x8b, 0x04, 0x5e], 0x8b),             // scale 2
        (&[0x46, 0x8b, 0x04, 0x1f], 0x8b),             // RDI base
        (&[0x46, 0x8b, 0x0c, 0x1e], 0x8b),             // R9D destination
        (&[0x44, 0x8b, 0x04, 0x1e], 0x8b),             // REX.X clear
        (&[0x45, 0x8b, 0x04, 0x1e], 0x8b),             // REX.X clear
        (&[0x46, 0x8b, 0x44, 0x1e, 0], 0x8b),          // disp8=0
        (&[0x46, 0x8b, 0x84, 0x1e, 0, 0, 0, 0], 0x8b), // disp32=0
        (&[0x46, 0x8b, 0x04, 0x9e], 0x8b),             // scale 4
        (&[0x8b, 0x04, 0x1e], 0x8b),                   // no REX.R/X
        (&[0x4e, 0x8b, 0x04, 0x1e], 0x8b),             // REX.W
        (&[0x66, 0x46, 0x8b, 0x04, 0x1e], 0x8b),       // operand-size prefix
        (&[0x67, 0x46, 0x8b, 0x04, 0x1e], 0x8b),       // address-size prefix
        (&[0xf3, 0x46, 0x8b, 0x04, 0x1e], 0x8b),       // REP prefix
        (&[0x64, 0x46, 0x8b, 0x04, 0x1e], 0x8b),       // FS override
        (&[0x65, 0x46, 0x8b, 0x04, 0x1e], 0x8b),       // GS override
        (&[0x46, 0x89, 0x04, 0x1e], 0x89),             // store direction
    ];
    for (bytes, opcode) in cases {
        let mut memory = Memory::new(bytes);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        let before = cpu.clone();
        let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

        assert_eq!(
            result.exit,
            PagedProbeExit::Unsupported { opcode: *opcode },
            "bytes {bytes:02x?}"
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(result.rflags_defined, DEFINED);
        assert_eq!(cpu, before, "bytes {bytes:02x?}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
    }
}

