#[test]
fn rust_helper_mov_rax_rsi_plus_r11_disp8_10_neighbours_stay_unsupported() {
    let cases: &[(&[u8], u8)] = &[
        (&[0x4a, 0x8b, 0x44, 0x1e, 0x0f], 0x8b),       // disp8=0x0f
        (&[0x4a, 0x8b, 0x44, 0x1e, 0x11], 0x8b),       // disp8=0x11
        (&[0x4e, 0x8b, 0x44, 0x1e, 0x10], 0x8b),       // REX.R selects R8
        (&[0x48, 0x8b, 0x44, 0x1e, 0x10], 0x8b),       // REX.X clear
        (&[0x42, 0x8b, 0x44, 0x1e, 0x10], 0x8b),       // REX.W clear
        (&[0x4b, 0x8b, 0x44, 0x1e, 0x10], 0x8b),       // REX.B changes base
        (&[0x4a, 0x8b, 0x44, 0x1f, 0x10], 0x8b),       // RDI base
        (&[0x4a, 0x8b, 0x44, 0x16, 0x10], 0x8b),       // R10 index
        (&[0x4a, 0x8b, 0x44, 0x5e, 0x10], 0x8b),       // scale 2
        (&[0x66, 0x4a, 0x8b, 0x44, 0x1e, 0x10], 0x8b), // operand prefix
        (&[0x67, 0x4a, 0x8b, 0x44, 0x1e, 0x10], 0x8b), // address prefix
        (&[0x4a, 0x89, 0x44, 0x1e, 0x10], 0x89),       // store direction
    ];
    for (bytes, opcode) in cases {
        let mut memory = Memory::new(bytes);
        let mut cpu = state();
        cpu.gpr = gpr_patterns();
        let before = cpu.clone();
        let result = step(&mut cpu, &mut memory, &mut Pio::default(), ring0());

        assert_eq!(
            result.exit,
            PagedProbeExit::Unsupported { opcode: *opcode },
            "bytes {bytes:02x?}"
        );
        assert_eq!(result.instructions_executed, 0);
        assert_eq!(result.rflags_defined, DEFINED);
        assert_eq!(cpu, before, "bytes {bytes:02x?}");
        assert_eq!((memory.reads, memory.writes), (0, 0));
    }
}

